import React, { useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import { useAudio } from '../../contexts/AudioContext';

const AudioPlayer: React.FC = () => {
  const location = useLocation();
  const { currentTrack, playLandingMusic, playGameMusic, isPlaying } = useAudio();
  const hasTriedPlayRef = useRef(false);
  
  // Intentar reproducir la música cuando se monta el componente
  useEffect(() => {
    if (!hasTriedPlayRef.current) {
      hasTriedPlayRef.current = true;
      
      // Rutas que deberían tener música de la landing page
      const landingRoutes = ['/', '/login', '/register'];
      const isLandingRoute = landingRoutes.includes(location.pathname);
      
      const attemptInitialPlay = async () => {
        try {
          if (isLandingRoute) {
            await playLandingMusic();
          } else {
            await playGameMusic();
          }
        } catch (error) {
          console.error("Error en reproducción inicial:", error);
        }
      };
      
      attemptInitialPlay();
      
      // Programar múltiples intentos
      const timers: number[] = [];
      [500, 1500, 3000].forEach(delay => {
        const timer = window.setTimeout(() => {
          if (!isPlaying) {
            if (isLandingRoute) {
              playLandingMusic().catch(e => console.warn(`Error en intento programado:`, e));
            } else {
              playGameMusic().catch(e => console.warn(`Error en intento programado:`, e));
            }
          }
        }, delay);
        timers.push(timer);
      });
      
      return () => {
        timers.forEach(t => window.clearTimeout(t));
      };
    }
  }, [playLandingMusic, playGameMusic, location.pathname, isPlaying]);
  
  // Cambiar la música según la ruta
  useEffect(() => {
    // Rutas que deberían tener música de la landing page
    const landingRoutes = ['/', '/login', '/register'];
    
    const changeMusic = async () => {
      // Comprobar si estamos en la landing page o una ruta relacionada
      if (landingRoutes.includes(location.pathname)) {
        if (currentTrack !== 'landing') {
          await playLandingMusic();
        }
      } else {
        // Para cualquier otra ruta, reproducir la música del juego
        if (currentTrack !== 'game') {
          await playGameMusic();
        }
      }
    };
    
    changeMusic();
  }, [location.pathname, currentTrack, playLandingMusic, playGameMusic]);
  
  // Este componente no renderiza nada visible
  return null;
};

export default AudioPlayer;
